select next_value, id from final table (merge into counter_rows cre1_0 using (values (?,next value for tck_seq)) excluded(id,next_value) on (cre1_0.id=excluded.id) when matched then update set next_value=(cre1_0.next_value+cast(? as bigint)) when not matched then insert (id,next_value) values (excluded.id,excluded.next_value))
